 @Test void payrollAdapterConsumesSameNetArrangementSourcesAndStaleChangeBlocks(){policy("default_normal");time.at("2026-12-01T12:00:00Z");var month=YearMonth.of(2026,11);daily.refresh(admin,store,new RefreshWrite(month,List.of(employee)));var profile=payProfile(new PayrollDtos.Rule("hourly","100","8","44",false,"1.5",List.of(),new PayrollDtos.Generation("attendance",List.of(1,2,3,4,5))));var adapter=new AttendancePayrollSources(daily);var first=adapter.capture(tenant,company,employee,month,profile);assertThat(first.issues()).isEmpty();assertThat(first.sources()).allSatisfy(ref->{assertThat(ref.sourceType()).isEqualTo("arrangement");assertThat(ref.evidence().actualSeconds()).isNull();});long seconds=first.sources().stream().filter(PayrollDtos.SourceRef::payable).mapToLong(PayrollDtos.SourceRef::workSeconds).sum();assertThat(daily.month(admin,store,month,employee,null,null,30,0).employees().getFirst().totals().workSeconds()).isEqualTo(seconds);daily.refresh(admin,store,new RefreshWrite(month,List.of(employee)));assertThat(adapter.capture(tenant,company,employee,month,profile).sources()).isEqualTo(first.sources());leave();var stale=adapter.capture(tenant,company,employee,month,profile);assertThat(stale.issues()).contains("APPROVAL_STALE");assertThat(stale.sources()).extracting(PayrollDtos.SourceRef::sourceId).doesNotHaveDuplicates();}
 @Test void contractSeparateAndIncludedUseOnlyExplicitExtraAndIgnoreRawClock(){policy("contract");time.at("2026-12-01T12:00:00Z");var month=YearMonth.of(2026,11);var extra=exceptions.submit(worker,store,UUID.randomUUID(),new ExceptionWrite(employee,company,date(),"extra_work",null,Instant.parse("2026-11-02T11:00:00Z"),Instant.parse("2026-11-02T12:00:00Z"),"Contract extra unit"));exceptions.decide(admin,store,extra.id(),new DecisionWrite(1L,"approved","Verified contract unit"));var adapter=new AttendancePayrollSources(daily);var separate=contractRule("separate");var captured=adapter.capture(tenant,company,employee,month,payProfile(separate));assertThat(captured.issues()).isEmpty();assertThat(captured.sources()).allSatisfy(ref->{assertThat(ref.sourceType()).isEqualTo("contract");assertThat(ref.evidence().actualSeconds()).isNull();assertThat(ref.evidence().approvedSeconds()).isNull();assertThat(ref.workSeconds()).isZero();});var units=PayrollGeneration.contractUnits(separate,captured.sources(),month,month.atDay(1),month.atEndOfMonth());assertThat(units.overtimeSeconds()).isEqualTo(3600);var calculatorRule=new PayCalculator.Rule("monthly",new java.math.BigDecimal("3000"),new java.math.BigDecimal("8"),new java.math.BigDecimal("44"),false,new java.math.BigDecimal("1.5"));var separatePay=new PayCalculator().calculateContract(calculatorRule,units,new PayCalculator.Units(units.workingDays(),units.payableDays(),true),List.of(),List.of());assertThat(separatePay.overtimePay()).isPositive();var included=PayrollGeneration.contractUnits(contractRule("included"),captured.sources(),month,month.atDay(1),month.atEndOfMonth());var includedPay=new PayCalculator().calculateContract(calculatorRule,included,new PayCalculator.Units(included.workingDays(),included.payableDays(),true),List.of(),List.of());assertThat(includedPay.overtimePay()).isZero();assertThat(includedPay.basicPay()).isEqualByComparingTo(separatePay.basicPay());var shift=new SchedulingDtos.Shift(UUID.randomUUID(),"Historical clock","09:00","17:00",false,"none",0,0,0,0,false,true,1);schedules.saveShift(tenant,store,shift);var schedule=new SchedulingDtos.Schedule(UUID.randomUUID(),employee,"Alice","E001",shift.id(),date(),Instant.parse("2026-11-02T01:00:00Z"),Instant.parse("2026-11-02T09:00:00Z"),"Asia/Singapore","scheduled",shift,company,1);schedules.save(tenant,store,schedule);new AttendanceRepository(jdbc,json).save(tenant,new AttendanceDtos.Session(UUID.randomUUID(),schedule.id(),employee,store,schedule.startAt(),schedule.endAt(),null,List.of(),false,1));assertThat(adapter.capture(tenant,company,employee,month,payProfile(separate)).sources()).isEqualTo(captured.sources());assertThat(jdbc.queryForObject("select count(*) from workforce_approvals where tenant_id=?",Long.class,tenant)).isZero();}
 @Test void payrollAdapterRejectsAttendancePolicyAndProfileModeMismatch(){policy("contract");var profile=payProfile(new PayrollDtos.Rule("hourly","100","8","44",false,"1.5",List.of(),new PayrollDtos.Generation("attendance",List.of(1,2,3,4,5))));assertThat(new AttendancePayrollSources(daily).capture(tenant,company,employee,YearMonth.of(2026,11),profile).issues()).contains("WORK_MODE_PAYROLL_MISMATCH");}
 private SchedulingDtos.Schedule scheduleAt(String start,String end){var shift=new SchedulingDtos.Shift(UUID.randomUUID(),"Explicit interval","22:00","06:00",true,"none",0,0,0,0,false,true,1);schedules.saveShift(tenant,store,shift);var schedule=new SchedulingDtos.Schedule(UUID.randomUUID(),employee,"Alice","E001",shift.id(),date(),Instant.parse(start),Instant.parse(end),"Asia/Singapore","scheduled",shift,company,1);schedules.save(tenant,store,schedule);return schedule;}
 @Test void overnightLeaveAndAbsenceKeepOriginalWorkDateAndWrongDayIsRejected(){policies.insert(tenant,adminId,new PolicyVersion(UUID.randomUUID(),employee,company,store,LocalDate.of(2026,10,1),"default_normal","personal",null,0,new Arrangement(List.of(1,2,3,4,5,6,7),LocalTime.of(22,0),480,0,null),"Asia/Singapore",1));UUID type=UUID.randomUUID();new LeaveTypeRepository(jdbc).save(tenant,store,new LeaveDtos.LeaveType(type,"Night leave",true,true,1));var leave=exceptions.submit(worker,store,UUID.randomUUID(),new ExceptionWrite(employee,company,date(),"leave",type,Instant.parse("2026-11-02T17:00:00Z"),Instant.parse("2026-11-02T18:00:00Z"),"Overnight later segment"));exceptions.decide(admin,store,leave.id(),new DecisionWrite(1L,"approved","Approved"));scheduleAt("2026-11-02T14:00:00Z","2026-11-02T22:00:00Z");var absence=exceptions.submit(worker,store,UUID.randomUUID(),new ExceptionWrite(employee,company,date(),"absence",null,Instant.parse("2026-11-02T19:00:00Z"),Instant.parse("2026-11-02T20:00:00Z"),"Overnight absence"));exceptions.decide(admin,store,absence.id(),new DecisionWrite(1L,"approved","Confirmed"));daily.refresh(admin,store,new RefreshWrite(YearMonth.of(2026,11),List.of(employee)));assertThat(day().paidLeaveSeconds()).isEqualTo(3600);assertThat(day().workSeconds()).isEqualTo(21600);assertThatThrownBy(()->exceptions.submit(worker,store,UUID.randomUUID(),new ExceptionWrite(employee,company,date().plusDays(1),"leave",type,Instant.parse("2026-11-02T17:00:00Z"),Instant.parse("2026-11-02T18:00:00Z"),"Wrong working day"))).extracting("code").isEqualTo("WORKFORCE_INVALID");var extra=exceptions.submit(worker,store,UUID.randomUUID(),new ExceptionWrite(employee,company,date(),"extra_work",null,Instant.parse("2026-11-02T22:00:00Z"),Instant.parse("2026-11-02T23:00:00Z"),"Adjacent after overnight shift"));assertThat(extra.workDate()).isEqualTo(date());assertThatThrownBy(()->exceptions.submit(worker,store,UUID.randomUUID(),new ExceptionWrite(employee,company,date(),"extra_work",null,Instant.parse("2026-11-02T22:00:00Z"),Instant.parse("2026-11-03T17:00:00Z"),"Crosses next workday boundary"))).extracting("code").isEqualTo("WORKFORCE_INVALID");assertThatThrownBy(()->exceptions.submit(worker,store,UUID.randomUUID(),new ExceptionWrite(employee,company,date(),"extra_work",null,Instant.parse("2026-11-03T22:00:00Z"),Instant.parse("2026-11-03T23:00:00Z"),"Unrelated next shift day"))).extracting("code").isEqualTo("WORKFORCE_INVALID");}
 @Test void futureApprovedExtraCannotBecomeEffectiveBeforeIntervalEnds(){policy("default_normal");var e=exceptions.submit(worker,store,UUID.randomUUID(),new ExceptionWrite(employee,company,date(),"extra_work",null,Instant.parse("2026-11-02T11:00:00Z"),Instant.parse("2026-11-02T13:00:00Z"),"Later extra work"));exceptions.decide(admin,store,e.id(),new DecisionWrite(1L,"approved","Approved interval"));time.at("2026-11-02T12:00:00Z");daily.refresh(admin,store,new RefreshWrite(YearMonth.of(2026,11),List.of(employee)));assertThat(day().workSeconds()).isNull();assertThat(day().issues()).contains("EXTRA_WORK_NOT_ENDED");assertThat(daily.evaluateForSystem(tenant,company,employee,date()).state()).isEqualTo("pending");time.at("2026-11-02T13:00:00Z");daily.refresh(admin,store,new RefreshWrite(YearMonth.of(2026,11),List.of(employee)));assertThat(day().state()).isEqualTo("system_valid");assertThat(day().workSeconds()).isEqualTo(36000);}
 @Test void scheduledHolidayRetainsCandidateHoursForLawfulHumanReview(){policy("default_normal");scheduleAt("2026-11-02T01:00:00Z","2026-11-02T09:00:00Z");new CalendarRepository(jdbc).save(tenant,store,new CalendarDtos.CalendarEvent(UUID.randomUUID(),date(),"public_holiday","Scheduled holiday",true,1));daily.refresh(admin,store,new RefreshWrite(YearMonth.of(2026,11),List.of(employee)));var d=day();assertThat(d.issues()).containsExactly("CALENDAR_REVIEW_REQUIRED");assertThat(d.snapshot().get("candidateWorkSeconds")).isInstanceOf(Number.class);daily.review(admin,store,d.sourceId(),new DayReviewWrite(employee,company,date(),d.version(),d.sourceFingerprint(),"Verified holiday shift"));assertThat(day().state()).isEqualTo("human_valid");assertThat(day().workSeconds()).isEqualTo(28800);}
 @Test void oldLeaveEntryCannotOverlapNewExceptionsAndNewEntryCannotOverlapOldLeave(){policy("default_normal");var schedule=scheduleAt("2026-11-02T01:00:00Z","2026-11-02T09:00:00Z");UUID type=UUID.randomUUID();new LeaveTypeRepository(jdbc).save(tenant,store,new LeaveDtos.LeaveType(type,"Scoped",true,true,1));var audit=new WorkforceAudit(logs,new ObjectMapper().findAndRegisterModules());var legacy=proxy(new LeaveService(access,new AttendanceAccess(access,repository,schedules),repository,schedules,new LeaveTypeRepository(jdbc),new LeaveRepository(jdbc),audit,time));var first=exceptions.submit(worker,store,UUID.randomUUID(),new ExceptionWrite(employee,company,date(),"leave",type,Instant.parse("2026-11-02T02:00:00Z"),Instant.parse("2026-11-02T03:00:00Z"),"New first"));assertThatThrownBy(()->legacy.submit(worker,store,UUID.randomUUID(),new LeaveDtos.LeaveWrite(schedule.id(),type,first.startAt(),first.endAt(),"Old overlap"))).extracting("code").isEqualTo("WORKFORCE_LEAVE_OVERLAP");var old=legacy.submit(worker,store,UUID.randomUUID(),new LeaveDtos.LeaveWrite(schedule.id(),type,Instant.parse("2026-11-02T04:00:00Z"),Instant.parse("2026-11-02T05:00:00Z"),"Old first"));assertThatThrownBy(()->exceptions.submit(worker,store,UUID.randomUUID(),new ExceptionWrite(employee,company,date(),"leave",type,old.startAt(),old.endAt(),"New overlap"))).extracting("code").isEqualTo("WORKFORCE_EXCEPTION_OVERLAP");days.create(tenant,new IntervalException(UUID.randomUUID(),employee,company,store,date(),"absence",null,null,false,old.startAt(),old.endAt(),"Pre-existing conflicting exception","approved",employeeAccount,adminId,"Historical overlap","approved",1,time.instant()));assertThatThrownBy(()->legacy.decide(admin,store,old.id(),new AttendanceDtos.DecisionWrite(1L,"approved","Must reject overlap"))).extracting("code").isEqualTo("WORKFORCE_LEAVE_OVERLAP");}
 @Test void contractAndFreeKeepLegacyScheduleLeavePendingAndApprovedFacts(){policy("contract");var schedule=scheduleAt("2026-11-02T01:00:00Z","2026-11-02T09:00:00Z");UUID type=UUID.randomUUID();new LeaveTypeRepository(jdbc).save(tenant,store,new LeaveDtos.LeaveType(type,"Unpaid original leave",false,true,1));var legacy=proxy(new LeaveService(access,new AttendanceAccess(access,repository,schedules),repository,schedules,new LeaveTypeRepository(jdbc),new LeaveRepository(jdbc),new WorkforceAudit(logs,new ObjectMapper().findAndRegisterModules()),time));var leave=legacy.submit(worker,store,UUID.randomUUID(),new LeaveDtos.LeaveWrite(schedule.id(),type,Instant.parse("2026-11-02T02:00:00Z"),Instant.parse("2026-11-02T04:00:00Z"),"Original leave reason"));assertThat(day().issues()).contains("PENDING_REQUEST");legacy.decide(admin,store,leave.id(),new AttendanceDtos.DecisionWrite(1L,"approved","Approved original"));assertThat(day().unpaidLeaveSeconds()).isEqualTo(7200);assertThat(day().actualSeconds()).isNull();assertThat(day().workSeconds()).isNull();jdbc.update("delete from workforce_attendance_policies where tenant_id=?",tenant);policy("free");assertThat(day().unpaidLeaveSeconds()).isEqualTo(7200);legacy.decide(worker,store,leave.id(),new AttendanceDtos.DecisionWrite(2L,"cancel_requested","Cancellation pending"));assertThat(day().issues()).contains("PENDING_REQUEST");assertThat(json.write(daily.month(worker,store,YearMonth.of(2026,11),employee,null,null,30,0))).doesNotContain("Original leave reason","Approved original");}
 @Test void approvedClockOverrunAndExtraIntervalCannotPaySameActualSecondsTwice(){policy("clock");var schedule=scheduleAt("2026-11-02T01:00:00Z","2026-11-02T09:00:00Z");new AttendanceRepository(jdbc,json).save(tenant,new AttendanceDtos.Session(UUID.randomUUID(),schedule.id(),employee,store,schedule.startAt(),Instant.parse("2026-11-02T11:00:00Z"),null,List.of(),false,1));var source=new ApprovalSources(new AttendanceRepository(jdbc,json),new LeaveRepository(jdbc),new CalendarRepository(jdbc),json,time);var raw=source.read(tenant,store,schedule);new ApprovalRepository(jdbc,json).save(tenant,store,employee,new ApprovalDtos.Approval(schedule.id(),1,source.fingerprint(raw),36000,0,0,raw,adminId,"Verified actual overrun",time.instant()));var extra=exceptions.submit(worker,store,UUID.randomUUID(),new ExceptionWrite(employee,company,date(),"extra_work",null,schedule.endAt(),Instant.parse("2026-11-02T11:00:00Z"),"Overlapping actual overrun"));exceptions.decide(admin,store,extra.id(),new DecisionWrite(1L,"approved","Approved separate fact"));daily.refresh(admin,store,new RefreshWrite(YearMonth.of(2026,11),List.of(employee)));assertThat(day().issues()).contains("EXTRA_WORK_OVERLAP");assertThat(day().workSeconds()).isNull();assertThat(day().state()).isEqualTo("pending");}
